def comps(cells):
    cells=set(cells); out=[]
    while cells:
        s=next(iter(cells)); st=[s]; comp=[s]; cells.discard(s)
        while st:
            p=st.pop()
            for d in((1,0),(-1,0),(0,1),(0,-1)):
                q=(p[0]+d[0],p[1]+d[1])
                if q in cells: cells.discard(q); comp.append(q); st.append(q)
        out.append(comp)
    return out

