    out=[[9]*ww for _ in range(hh)]
    for p in {(0,0),(0,ww-1),(hh-1,0),(hh-1,ww-1)}: out[p[0]][p[1]]=8
    def blocked(cells):
        return any(not(0<=r<hh and 0<=c<ww) or out[r][c]!=9 for r,c in cells)
    # repeatedly move each component one step toward its nearest edge (per axis independently)
    occ={p for p in {(0,0),(0,ww-1),(hh-1,0),(hh-1,ww-1)} | {(r,c) for r in range(hh) for c in range(ww) if out[r][c]==5}}
    changed=True
